CREATE EXTENSION IF NOT EXISTS pg_trgm;
DO $$ BEGIN CREATE TYPE health_status AS ENUM ('healthy','degraded','offline','unknown'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE sync_status AS ENUM ('pending','running','completed','failed','partial'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS vod_sources (id text PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL, adapter_name text NOT NULL, base_url text NOT NULL, config_jsonb jsonb NOT NULL DEFAULT '{}', priority integer NOT NULL DEFAULT 100, enabled boolean NOT NULL DEFAULT true, health_status health_status NOT NULL DEFAULT 'unknown', last_health_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS source_play_lines (id text PRIMARY KEY, source_id text NOT NULL REFERENCES vod_sources(id), line_code text NOT NULL, line_name text NOT NULL, format_hint text, priority integer NOT NULL DEFAULT 100, enabled boolean NOT NULL DEFAULT true, health_status health_status NOT NULL DEFAULT 'unknown', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_id,line_code));
CREATE TABLE IF NOT EXISTS categories (id text PRIMARY KEY, name text NOT NULL, parent_id text REFERENCES categories(id), sort_order integer NOT NULL DEFAULT 0, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS source_categories (source_id text NOT NULL REFERENCES vod_sources(id), source_category_id text NOT NULL, source_category_name text NOT NULL, category_id text REFERENCES categories(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_id,source_category_id));
CREATE TABLE IF NOT EXISTS videos (id text PRIMARY KEY, title text NOT NULL, normalized_title text NOT NULL, poster_url text, backdrop_url text, description text, category_id text REFERENCES categories(id), year integer, status text, remarks text, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS videos_normalized_title_idx ON videos(normalized_title);
CREATE INDEX IF NOT EXISTS videos_normalized_title_trgm_idx ON videos USING gin(normalized_title gin_trgm_ops);
CREATE INDEX IF NOT EXISTS videos_category_enabled_updated_idx ON videos(category_id,enabled,updated_at DESC);
CREATE TABLE IF NOT EXISTS source_videos (id text PRIMARY KEY, video_id text NOT NULL REFERENCES videos(id), source_id text NOT NULL REFERENCES vod_sources(id), source_video_id text NOT NULL, source_category_id text, source_updated_at timestamptz, content_hash text NOT NULL, raw_payload_jsonb jsonb NOT NULL DEFAULT '{}', last_seen_run_id text, last_synced_at timestamptz NOT NULL DEFAULT now(), missing_count integer NOT NULL DEFAULT 0, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_id,source_video_id));
CREATE INDEX IF NOT EXISTS source_videos_seen_idx ON source_videos(source_id,last_seen_run_id);
CREATE TABLE IF NOT EXISTS episodes (id text PRIMARY KEY, video_id text NOT NULL REFERENCES videos(id), name text NOT NULL, normalized_name text NOT NULL, episode_no integer, sort_order integer NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS episodes_video_enabled_sort_idx ON episodes(video_id,enabled,sort_order);
CREATE TABLE IF NOT EXISTS source_episodes (id text PRIMARY KEY, episode_id text NOT NULL REFERENCES episodes(id), source_video_id text NOT NULL REFERENCES source_videos(id), play_line_id text NOT NULL REFERENCES source_play_lines(id), source_episode_key text NOT NULL, source_episode_name text NOT NULL, source_locator_jsonb jsonb NOT NULL, last_seen_run_id text, last_synced_at timestamptz NOT NULL DEFAULT now(), enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_video_id,play_line_id,source_episode_key));
CREATE INDEX IF NOT EXISTS source_episodes_episode_enabled_idx ON source_episodes(episode_id,enabled);
CREATE TABLE IF NOT EXISTS installations (id text PRIMARY KEY, token_hash text NOT NULL UNIQUE, token_version integer NOT NULL DEFAULT 1, platform text NOT NULL, app_version text NOT NULL, last_seen_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS watch_history (id text PRIMARY KEY, owner_type text NOT NULL, owner_id text NOT NULL REFERENCES installations(id), video_id text NOT NULL REFERENCES videos(id), episode_id text NOT NULL REFERENCES episodes(id), position_seconds integer NOT NULL, duration_seconds integer NOT NULL, completed boolean NOT NULL, client_updated_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_type,owner_id,video_id,episode_id));
CREATE INDEX IF NOT EXISTS watch_history_owner_updated_idx ON watch_history(owner_type,owner_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS playback_sessions (id text PRIMARY KEY, owner_id text NOT NULL REFERENCES installations(id), video_id text NOT NULL REFERENCES videos(id), episode_id text NOT NULL REFERENCES episodes(id), source_id text NOT NULL REFERENCES vod_sources(id), play_line_id text NOT NULL REFERENCES source_play_lines(id), status text NOT NULL, resolved_at timestamptz, expires_at timestamptz, first_event_at timestamptz, last_event_at timestamptz, last_event_type text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sync_runs (id text PRIMARY KEY, source_id text NOT NULL REFERENCES vod_sources(id), trigger_type text NOT NULL, status sync_status NOT NULL DEFAULT 'pending', cursor_jsonb jsonb NOT NULL DEFAULT '{}', started_at timestamptz, finished_at timestamptz, fetched_count integer NOT NULL DEFAULT 0, changed_count integer NOT NULL DEFAULT 0, skipped_count integer NOT NULL DEFAULT 0, failed_count integer NOT NULL DEFAULT 0, error_summary_jsonb jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sync_runs_source_started_idx ON sync_runs(source_id,started_at DESC);
CREATE TABLE IF NOT EXISTS admin_audit_logs (id text PRIMARY KEY, actor_type text NOT NULL, actor_id text NOT NULL, action text NOT NULL, target_type text NOT NULL, target_id text NOT NULL, request_id text NOT NULL, before_jsonb jsonb, after_jsonb jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS catalog_state (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), version bigint NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO catalog_state(singleton,version) VALUES(true,1) ON CONFLICT DO NOTHING;
